        // Manual epoch mode (legacy behavior)
        if (duration == 0) {
            return currentEpoch[questionId];
        }

        // Time-based epoch mode (automatic rolling)
        uint256 elapsed = block.timestamp - epochStartTime[questionId];
        return 1 + (elapsed / duration);
